package dev.qiandeng.maw;

import com.google.gson.*;
import com.mojang.brigadier.arguments.StringArgumentType;
import net.minecraft.commands.Commands;
import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.*;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.RegisterCommandsEvent;
import net.neoforged.neoforge.event.entity.item.ItemTossEvent;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.event.level.BlockEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Consumer;

/** Player UI, compatible CLI and same-body SDK share these actual game services. */
final class RpgMigrationBridge {
    static final Set<String> READS=Set.of("rpg_state","rpg_skills","rpg_protect","rpg_lands","rpg_arena_status","rpg_stash_state","rpg_recycle_list","rpg_recycle_quote","rpg_shop_list");
    static final Set<String> WRITES=Set.of("rpg_skill_learn","rpg_skill_upgrade","rpg_skill_cast","rpg_skill_bind","rpg_skill_imprint","rpg_profession_choose","rpg_land_claim","rpg_land_release","rpg_land_trust","rpg_land_untrust","rpg_arena_lobby","rpg_arena_start","rpg_arena_resume","rpg_arena_leave","rpg_stash_open","rpg_recycle_sell","rpg_shop_buy","rpg_open");
    private static final Map<UUID,String> SENT=new HashMap<>();
    private static final Map<UUID,Long> LAST_SENT=new HashMap<>();
    static JsonObject load(String path){try(var stream=RpgMigrationBridge.class.getResourceAsStream(path)){if(stream==null)throw new IllegalStateException("rpg_catalog_missing");return JsonParser.parseReader(new InputStreamReader(stream,StandardCharsets.UTF_8)).getAsJsonObject();}catch(java.io.IOException failure){throw new IllegalStateException("rpg_catalog_unreadable",failure);}}
    static void register(net.neoforged.bus.api.IEventBus bus){
        RpgMessages.register(bus);RpgSkills.register();RpgProtection.register();RpgTrials.register();SystemCallBridge.register();
        NeoForge.EVENT_BUS.addListener(RpgMigrationBridge::commands);
        NeoForge.EVENT_BUS.addListener((ServerTickEvent.Post e)->{RpgSkills.tick(e.getServer());RpgTrials.tick(e.getServer());if(e.getServer().getTickCount()%20!=0)return;for(ServerPlayer p:e.getServer().getPlayerList().getPlayers())if(PlayerAuthBridge.authenticated(p)){JsonObject hud=hud(p);String fingerprint=hud.toString();long now=System.currentTimeMillis();if(!fingerprint.equals(SENT.get(p.getUUID()))||now-LAST_SENT.getOrDefault(p.getUUID(),0L)>=5000){RpgMessages.state(p,hud,!fingerprint.equals(SENT.get(p.getUUID())),now-LAST_SENT.getOrDefault(p.getUUID(),0L)>=5000);SENT.put(p.getUUID(),fingerprint);LAST_SENT.put(p.getUUID(),now);}}});
        NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerLoggedOutEvent e)->{if(e.getEntity() instanceof ServerPlayer p){RpgSkills.clearFlight(p);SENT.remove(p.getUUID());LAST_SENT.remove(p.getUUID());}});
        NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerRespawnEvent e)->{if(e.getEntity() instanceof ServerPlayer p){RpgSkills.clearFlight(p);SENT.remove(p.getUUID());}});
        NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerChangedDimensionEvent e)->{if(e.getEntity() instanceof ServerPlayer p)RpgSkills.clearFlight(p);});
        NeoForge.EVENT_BUS.addListener((BlockEvent.BreakEvent e)->{if(e.getPlayer() instanceof ServerPlayer p&&!p.isSpectator()&&!p.getAbilities().instabuild&&RpgProtection.allowed(p,"break",e.getPos())){String id=net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(e.getState().getBlock()).getPath();if(id.endsWith("_ore")||id.equals("ancient_debris"))RpgStore.evidence(p,"minedOres",1);}});
        NeoForge.EVENT_BUS.addListener((ItemTossEvent e)->{if(!RpgStorage.bound(e.getEntity().getItem())||!(e.getPlayer() instanceof ServerPlayer p)||e.getEntity().getItem().getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getBoolean("maw_guide"))return;e.setCanceled(true);ItemStack item=e.getEntity().getItem().copy();if(!p.getInventory().add(item))RpgStorage.enqueue(p,List.of(item));hint(p,"绑定道具不可丢弃；满包时安全存入个人试炼箱。");});
    }
    static JsonObject hud(ServerPlayer p){JsonObject r=new JsonObject();r.addProperty("schemaVersion",1);r.addProperty("bodyId",p.getUUID().toString());r.addProperty("playerUuid",p.getUUID().toString());r.add("mana",PlayerSpellBridge.manaState(p));JsonArray abilities=new JsonArray();
        RpgSkills.CATALOG.getAsJsonObject("skills").entrySet().stream().filter(e->RpgSkills.level(p,e.getKey())>0).limit(24).forEach(e->{JsonObject def=e.getValue().getAsJsonObject(),row=new JsonObject();String id=e.getKey();row.addProperty("id",id);row.addProperty("name",def.get("title").getAsString());row.addProperty("level",RpgSkills.level(p,id));row.addProperty("cooldownMs",def.get("cooldown-seconds").getAsLong()*1000);row.addProperty("cooldownRemainingMs",RpgSkills.remaining(p,id));row.addProperty("icon","minecraft:"+def.get("icon").getAsString().toLowerCase(Locale.ROOT));abilities.add(row);});r.add("abilities",abilities);
        JsonArray skills=new JsonArray();JsonObject evidence=RpgStore.object(RpgStore.player(p),"evidence");for(String id:List.of("mining","fighting")){int xp=RpgStore.integer(evidence,id.equals("mining")?"minedOres":"kills");JsonObject skill=new JsonObject();skill.addProperty("id",id);skill.addProperty("name",id.equals("mining")?"采矿实践":"战斗实践");skill.addProperty("level",xp/16+1);skill.addProperty("xp",xp%16);skill.addProperty("requiredXp",16);skills.add(skill);}r.add("skills",skills);return r;
    }
    static JsonObject state(ServerPlayer p){JsonObject r=new JsonObject();r.addProperty("schemaVersion",1);r.addProperty("playerUuid",p.getUUID().toString());r.addProperty("bodyId",p.getUUID().toString());r.addProperty("sampledAt",Instant.now().toString());r.add("mana",PlayerSpellBridge.manaState(p));r.add("skills",RpgSkills.state(p));r.add("stacia",SystemCallBridge.stacia(p));r.add("trial",RpgTrials.state(p));r.addProperty("balance",RpgStorage.wallet(p));r.addProperty("pendingRewardStacks",RpgStore.player(p).getAsJsonArray("pending").size());r.add("lastResults",RpgStore.object(RpgStore.player(p),"lastResults").deepCopy());r.addProperty("historicalPaperProgressImported",false);return r;}
    static void remember(ServerPlayer p,String key,JsonObject result){RpgStore.object(RpgStore.player(p),"lastResults").add(key,result.deepCopy());RpgStore.dirty(p);}
    static void rememberError(ServerPlayer p,String key,String code){JsonObject r=new JsonObject();r.addProperty("ok",false);r.addProperty("code",code);remember(p,key,r);}
    static void fields(JsonObject input,String kind){switch(kind){case "rpg_protect"->ModRequest.fields(input,"action","position");case "rpg_skill_learn","rpg_skill_upgrade","rpg_skill_cast","rpg_skill_bind"->ModRequest.fields(input,"skillId");case "rpg_skill_imprint"->ModRequest.fields(input,"skillId","expectedSnbt");case "rpg_profession_choose"->ModRequest.fields(input,"profession");case "rpg_land_claim"->ModRequest.fields(input,"landId","min","max");case "rpg_land_release"->ModRequest.fields(input,"landId");case "rpg_land_trust","rpg_land_untrust"->ModRequest.fields(input,"landId","targetUuid");case "rpg_stash_state","rpg_stash_open"->ModRequest.fields(input,"page");case "rpg_recycle_quote"->ModRequest.fields(input,"source","slot","count");case "rpg_recycle_sell"->ModRequest.fields(input,"quoteId");case "rpg_shop_buy"->ModRequest.fields(input,"offerId");case "rpg_arena_start"->ModRequest.fields(input,"difficulty");case "rpg_open"->ModRequest.fields(input,"menu","page");default->ModRequest.fields(input);}}
    static JsonObject invoke(ServerPlayer p,String kind,JsonObject input){PlayerAuthBridge.requireAuthenticated(p);fields(input,kind);String operation=kind.substring(4);JsonObject result;
        switch(operation){case "state"->result=state(p);case "skills"->result=RpgSkills.state(p);case "protect"->{result=RpgProtection.query(p,ModRequest.text(input,"action",16),ModRequest.position(input,"position"));RpgMessages.protection(p,result);}case "lands"->result=RpgProtection.list(p);case "arena_status"->result=RpgTrials.state(p);case "stash_state"->result=RpgStorage.state(p,ModRequest.integer(input,"page",1,10)-1);case "recycle_list"->result=RpgStorage.recyclable(p);case "recycle_quote"->result=RpgStorage.quote(p,input);case "recycle_sell"->result=RpgStorage.sell(p,ModRequest.text(input,"quoteId",36));case "shop_list"->result=RpgStorage.shop(p);case "shop_buy"->result=RpgStorage.buy(p,ModRequest.text(input,"offerId",32));case "stash_open"->{RpgStorage.open(p,ModRequest.integer(input,"page",1,10)-1);result=new JsonObject();}case "open"->{open(p,ModRequest.text(input,"menu",32),ModRequest.integer(input,"page",1,10));result=new JsonObject();}default->{if(operation.startsWith("skill_")||operation.equals("profession_choose"))result=RpgSkills.act(p,operation,input);else if(operation.startsWith("land_"))result=RpgProtection.act(p,operation,input);else if(operation.startsWith("arena_"))result=RpgTrials.act(p,operation,input);else throw new IllegalArgumentException("rpg_operation_not_found");}}
        if(!result.has("ok"))result.addProperty("ok",true);return result;
    }
    static void hint(ServerPlayer p,String message){p.sendSystemMessage(Component.literal(message));}
    private static JsonObject args(String key,String value){JsonObject r=new JsonObject();r.addProperty(key,value);return r;}
    private static int command(ServerPlayer p,String command,String raw){try{String[] a=raw.isBlank()?new String[0]:raw.trim().split("\\s+");switch(command){
        case "rpg"->{open(p,"guide",1);}
        case "protect"->{if(a.length!=4)throw new IllegalArgumentException("用法：/mycli protect break|place|use <x> <y> <z>；绝对整数坐标。回执仅 mcagent:protection。");RpgMessages.protection(p,RpgProtection.query(p,a[0],new BlockPos(Integer.parseInt(a[1]),Integer.parseInt(a[2]),Integer.parseInt(a[3]))));}
        case "skills","spells"->{if(a.length==0||a[0].equals("menu")){open(p,"skills",1);}else if(a[0].equals("points")){hint(p,"可用技能点："+RpgSkills.points(p)+"；初始6点，上限30；战斗、采矿、委托和试炼增加点数。");}else if(a[0].equals("list")||a[0].equals("mine")){for(var v:RpgSkills.state(p).getAsJsonArray("abilities")){JsonObject row=v.getAsJsonObject();if(a[0].equals("mine")&&row.get("level").getAsInt()==0)continue;hint(p,row.get("id").getAsString()+" · "+row.get("name").getAsString()+" Lv"+row.get("level").getAsInt()+"；/mycli skills info "+row.get("id").getAsString());}}else if(a.length==2&&Set.of("info","explain").contains(a[0])){JsonObject def=RpgSkills.definition(a[1]);hint(p,def.get("title").getAsString()+"："+def.get("description").getAsString()+" 新服实际等级参数与可学条件以 rpg.skills 为准；学习/升级耗点。");}else if(a.length==2&&Set.of("learn","upgrade").contains(a[0])){RpgSkills.act(p,"skill_"+a[0],args("skillId",a[1]));hint(p,"技能学习已保存；/mycli skills mine 查看。");}else throw new IllegalArgumentException("/mycli skills menu|list|mine|points|info <ID>|learn <ID>|upgrade <ID>");}
        case "cast"->{if(a.length!=1)throw new IllegalArgumentException("/mycli cast <技能ID>；先 skills list，失败不播放成功事件。");JsonObject r=RpgSkills.cast(p,a[0]);if(r.has("status"))hint(p,"探矿扫描开始；rpg.state 返回绝对坐标结果。请等待，勿重复施法。");else if(r.has("targets"))for(JsonElement e:r.getAsJsonArray("targets")){JsonObject t=e.getAsJsonObject();hint(p,"命中 "+t.get("name").getAsString()+"（"+t.get("type").getAsString()+"） "+t.get("position"));}}
        case "profession"->{if(a.length==2&&a[0].equals("choose")){RpgSkills.act(p,"profession_choose",args("profession",a[1]));hint(p,"职业已选择；学习历史和冷却保留。");}else open(p,"professions",1);}
        case "focus"->{if(a.length==2&&a[0].equals("bind")){RpgSkills.act(p,"skill_bind",args("skillId",a[1]));giveBound(p,"focus");}else if(a.length==1&&a[0].equals("give"))giveBound(p,"focus");else open(p,"skills",1);}
        case "tome"->{giveBound(p,"tome");open(p,"guide",1);}
        case "land"->{if(a.length==0||a[0].equals("menu")){open(p,"lands",1);}else if(a[0].equals("here")){JsonObject q=RpgProtection.query(p,"break",p.blockPosition());hint(p,q.has("landId")?"领地："+q.get("landId").getAsString():"这里没有自有领地；殖民地和其它模组保护仍适用。");}else if(a[0].equals("list")||a[0].equals("info")||a[0].equals("members")){hint(p,RpgProtection.list(p).toString());}else if(a.length==3&&Set.of("trust","untrust").contains(a[0])){JsonObject r=args("landId",a[1]);r.addProperty("targetUuid",a[2]);RpgProtection.act(p,"land_"+a[0],r);hint(p,"领地成员已保存。");}else if(a.length==8&&a[0].equals("claim")){JsonObject r=args("landId",a[1]);r.add("min",ModRequest.position(new BlockPos(Integer.parseInt(a[2]),Integer.parseInt(a[3]),Integer.parseInt(a[4]))));r.add("max",ModRequest.position(new BlockPos(Integer.parseInt(a[5]),Integer.parseInt(a[6]),Integer.parseInt(a[7]))));RpgProtection.act(p,"land_claim",r);hint(p,"领地已登记；land info 查看。");}else if(a.length==2&&a[0].equals("release")){RpgProtection.act(p,"land_release",args("landId",a[1]));}else throw new IllegalArgumentException("land menu|here|list|claim ID minX minY minZ maxX maxY maxZ|trust/untrust ID UUID|release ID");}
        case "arena"->{if(a.length>1&&a[0].equals("recycle")){economyCommand(p,"recycle",Arrays.copyOfRange(a,1,a.length));break;}if(a.length>1&&a[0].equals("shop")){economyCommand(p,"shop",Arrays.copyOfRange(a,1,a.length));break;}String action=a.length==0?"menu":a[0];if(action.equals("status")){JsonObject state=RpgTrials.state(p);hint(p,"本人参赛="+state.get("participant")+"，本人楼层="+state.get("floor")+"；全服楼层="+state.get("worldFloor")+"，剩余="+state.get("worldRemainingMonsters")+"，异常="+state.get("anomaly"));}else if(action.equals("menu"))open(p,"arena",1);else if(action.equals("stash")||action.equals("rewards")){int page=a.length==3&&a[1].equals("page")?Integer.parseInt(a[2]):1;RpgStorage.open(p,page-1);}else if(action.equals("shop"))open(p,"shop",1);else if(Set.of("lobby","start","resume","leave").contains(action)){RpgTrials.act(p,"arena_"+action,args("difficulty",a.length>1?a[1]:"normal"));}else if(action.equals("recycle"))open(p,"recycle",1);else throw new IllegalArgumentException("arena menu|status|lobby|start normal/adventure/apocalypse|resume|leave|stash [page 1-10]|shop|recycle");}
        case "town"->WandscapeMenus.open(p);
        default->throw new IllegalArgumentException("rpg_cli_unknown");}return 1;}catch(IllegalArgumentException error){hint(p,error.getMessage());return 0;}}
    private static void economyCommand(ServerPlayer p,String group,String[] a){JsonObject out;String action=a[0];if(group.equals("recycle")){if(action.equals("list"))out=RpgStorage.recyclable(p);else if(action.equals("quote")&&a.length==4){JsonObject args=args("source",a[1]);args.addProperty("slot",Integer.parseInt(a[2]));args.addProperty("count",Integer.parseInt(a[3]));out=RpgStorage.quote(p,args);}else if(action.equals("sell")&&a.length==2)out=RpgStorage.sell(p,a[1]);else throw new IllegalArgumentException("arena recycle list|quote bag/chest <slot> <count>|sell <quoteId>");}else {if(action.equals("list"))out=RpgStorage.shop(p);else if(action.equals("buy")&&a.length==2)out=RpgStorage.buy(p,a[1]);else if(action.equals("wallet")){out=new JsonObject();out.addProperty("balance",RpgStorage.wallet(p));}else throw new IllegalArgumentException("arena shop list|buy <offerId>|wallet");}out.addProperty("schemaVersion",1);out.addProperty("playerUuid",p.getUUID().toString());out.addProperty("action",group+"."+action);hint(p,"MC_ARENA_ECONOMY "+out);}
    private static void commands(RegisterCommandsEvent event){var root=Commands.literal("mycli").requires(s->s.getEntity() instanceof ServerPlayer p&&PlayerAuthBridge.authenticated(p));for(String name:List.of("rpg","protect","skills","spells","cast","profession","focus","tome","land","arena","town"))root.then(Commands.literal(name).executes(c->command(c.getSource().getPlayerOrException(),name,"")).then(Commands.argument("arguments",StringArgumentType.greedyString()).executes(c->command(c.getSource().getPlayerOrException(),name,StringArgumentType.getString(c,"arguments")))));event.getDispatcher().register(root);}
    private static final class Menu extends ChestMenu {final ServerPlayer owner;final Map<Integer,Consumer<ServerPlayer>> buttons;Menu(int id,Inventory inventory,ServerPlayer p,SimpleContainer c,Map<Integer,Consumer<ServerPlayer>> buttons){super(MenuType.GENERIC_9x3,id,inventory,c,3);owner=p;this.buttons=buttons;}@Override public void clicked(int slot,int button,ClickType type,Player who){if(who!=owner||!stillValid(who)||!getCarried().isEmpty()||type!=ClickType.PICKUP||button>1)return;Consumer<ServerPlayer> run=buttons.get(slot);if(run!=null)try{run.accept(owner);}catch(IllegalArgumentException e){hint(owner,e.getMessage());}}@Override public ItemStack quickMoveStack(Player who,int slot){return ItemStack.EMPTY;}@Override public boolean stillValid(Player who){return who==owner&&owner.isAlive()&&PlayerAuthBridge.authenticated(owner);}}
    private static ItemStack icon(Item item,String name,String... lore){ItemStack s=new ItemStack(item);s.set(DataComponents.CUSTOM_NAME,Component.literal(name));s.set(DataComponents.LORE,new ItemLore(Arrays.stream(lore).map(Component::literal).map(c->(Component)c).toList()));return s;}
    static void show(ServerPlayer p,String title,SimpleContainer c,Map<Integer,Consumer<ServerPlayer>> buttons){if(!p.containerMenu.getCarried().isEmpty())throw new IllegalArgumentException("clear_cursor_before_menu");p.openMenu(new SimpleMenuProvider((id,inv,who)->new Menu(id,inv,p,c,buttons),Component.literal(title)));}
    static void add(SimpleContainer c,Map<Integer,Consumer<ServerPlayer>> b,int slot,Item icon,String name,Consumer<ServerPlayer> action,String...lore){c.setItem(slot,icon(icon,name,lore));b.put(slot,action);}
    static void open(ServerPlayer p,String menu,int page){if(menu.equals("town")){WandscapeMenus.open(p);return;}if(Set.of("systemcall","stacia").contains(menu)){SystemCallBridge.open(p,menu);return;}SimpleContainer c=new SimpleContainer(27);Map<Integer,Consumer<ServerPlayer>> b=new HashMap<>();String title="冒险与技艺";
        switch(menu){case "guide"->{if(net.neoforged.fml.ModList.get().isLoaded("wandscape"))add(c,b,15,Items.BELL,"魔法小镇",WandscapeMenus::open,"建镇、法师施工与真实仓储");JsonObject d=RpgStore.player(p);title="命格书 · "+p.getGameProfile().getName();JsonObject guild=SocietyLifeBridge.state(p);add(c,b,22,Items.IRON_INGOT,guild.get("rank").getAsString()+" · 声望 "+guild.get("reputation"),q->SocietyLifeBridge.open(q,"current"),"通关 "+RpgStore.integer(RpgStore.object(d,"evidence"),"trialWins")+" 次 · 试炼死亡 "+RpgStore.integer(RpgStore.object(d,"evidence"),"trialDeaths"),"任务与余额按本人UUID读取");add(c,b,0,Items.NAME_TAG,"生命 "+p.getHealth()+"/"+p.getMaxHealth()+" · 职业 "+d.get("profession").getAsString(),q->{},"技能点 "+RpgSkills.points(p),"战斗/采矿/委托/试炼：真实事件成长","余额 "+RpgStorage.wallet(p)+" 灯币");add(c,b,2,Items.COMPASS,"技能 · 学习 · 升级 · 快捷施法",q->open(q,"skills",1),"施法消耗 Ars 原生魔力；无重复魔力池");add(c,b,4,Items.IRON_SWORD,"战士 · 法师 · 牧师",q->open(q,"professions",1));add(c,b,6,Items.OAK_FENCE,"领地归属与成员",q->open(q,"lands",1));add(c,b,8,Items.SPAWNER,"十五层试炼 · 难度与队伍",q->open(q,"arena",1));add(c,b,10,Items.CHEST,"个人奖励箱 · 540格",q->RpgStorage.open(q,0),"真箱子存取，没有拿不走的功能图标","第2-10页：/mycli arena stash page 2");add(c,b,12,Items.EMERALD,"补给商店与装备回收",q->open(q,"shop",1));add(c,b,14,Items.STICK,"领取灵纹法杖",q->giveBound(q,"focus"),"先从技能详情绑定；手持交互瞬发");add(c,b,16,Items.WRITTEN_BOOK,"领取命格书",q->giveBound(q,"tome"),"本人信息和界面导航；不可丢弃");add(c,b,18,Items.WRITABLE_BOOK,"公会委托与声望",q->SocietyLifeBridge.open(q,"quests"));add(c,b,20,Items.GOLD_INGOT,"市场 · 玩家订单",q->SocietyLifeBridge.open(q,"market"));add(c,b,24,Items.NAME_TAG,"Stacia Window · 天命与装备",q->SystemCallBridge.open(q,"stacia"),"本人实际生命、魔力、饥饿、坐标与耐久");add(c,b,25,Items.ENCHANTED_BOOK,"System Call · 神圣术",q->SystemCallBridge.open(q,"systemcall"),"咏唱或手柄快捷施法共用原技能");}
        case "professions"->{title="选择主战职业";int n=0;for(var e:RpgSkills.CATALOG.getAsJsonObject("professions").entrySet()){String id=e.getKey();add(c,b,n++,Items.IRON_SWORD,e.getValue().getAsJsonObject().get("title").getAsString(),q->{RpgSkills.act(q,"profession_choose",args("profession",id));open(q,"skills",1);},"仅解锁学习资格；技能点和历史保留");}}
        case "skills"->{title="技能罗盘 · 第"+page+"页 · "+RpgSkills.points(p)+"点";List<String> ids=new ArrayList<>(RpgSkills.CATALOG.getAsJsonObject("skills").keySet());int n=0;for(int i=(page-1)*18;i<Math.min(ids.size(),page*18);i++){String id=ids.get(i);JsonObject def=RpgSkills.definition(id);add(c,b,n++,net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse("minecraft:"+def.get("icon").getAsString().toLowerCase(Locale.ROOT))),def.get("title").getAsString()+" Lv"+RpgSkills.level(p,id),q->skillDetail(q,id),"ID: "+id,"点击学习 / 升级 / 绑定 / 施放");}if(page*18<ids.size())add(c,b,24,Items.ARROW,"下一页",q->open(q,"skills",page+1));if(page>1)add(c,b,23,Items.ARROW,"上一页",q->open(q,"skills",page-1));}
        case "lands"->{title="领地归属";int n=0;for(var e:RpgProtection.list(p).getAsJsonArray("lands")){if(n>=24)break;JsonObject row=e.getAsJsonObject();add(c,b,n++,Items.OAK_FENCE,row.get("id").getAsString(),q->hint(q,"主人 "+row.get("ownerUuid")+"；成员 "+row.get("members")),row.get("min").toString(),row.get("max").toString());}add(c,b,24,Items.OAK_SIGN,"登记身边15×15营地",q->{BlockPos at=q.blockPosition();JsonObject args=args("landId","camp_"+q.getUUID().toString().substring(0,8));args.add("min",ModRequest.position(at.offset(-7,-2,-7)));args.add("max",ModRequest.position(at.offset(7,14,7)));RpgProtection.act(q,"land_claim",args);open(q,"lands",1);},"不会覆盖已有领地或殖民地权限","拥有者可用land trust授权同伴UUID");}
        case "arena"->{title="试炼塔 · 选择难度与队伍";add(c,b,0,Items.COMPASS,"前往试炼入口",q->RpgTrials.act(q,"arena_lobby",new JsonObject()),"附近12格玩家一起开场","最多4人；目前独立一场");int n=2;for(String difficulty:List.of("normal","adventure","apocalypse")){add(c,b,n++,Items.IRON_SWORD,difficulty.equals("normal")?"普通":difficulty.equals("adventure")?"冒险":"末日",q->RpgTrials.act(q,"arena_start",args("difficulty",difficulty)),"须在入口；清层10秒后自动下一层","第7层60秒休息；满血续层");}add(c,b,8,Items.ENDER_PEARL,"断线后归队",q->RpgTrials.act(q,"arena_resume",new JsonObject()));add(c,b,10,Items.CHEST,"我的奖励箱",q->RpgStorage.open(q,0));add(c,b,12,Items.EMERALD,"补给与回收",q->open(q,"shop",1));add(c,b,14,Items.OAK_DOOR,"退出挑战回入口",q->RpgTrials.act(q,"arena_leave",new JsonObject()));add(c,b,16,Items.PAPER,"本人参赛="+RpgTrials.participant(p),q->command(q,"arena","status"));}
        case "shop"->{title="试炼补给 · "+RpgStorage.wallet(p)+"灯币";int n=0;for(JsonElement e:RpgStorage.shop(p).getAsJsonArray("offers")){JsonObject row=e.getAsJsonObject();String id=row.get("id").getAsString();add(c,b,n++,net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse(row.get("item").getAsString())),id+" ×"+row.get("count")+" · "+row.get("price")+"灯币",q->{RpgStorage.buy(q,id);open(q,"shop",1);},"满包时进个人箱或待领取队列");}add(c,b,22,Items.ANVIL,"回收未装备的重复装备",q->open(q,"recycle",1));}
        case "recycle"->{title="重复装备回收 · 报价后确认";int n=0;for(JsonElement e:RpgStorage.recyclable(p).getAsJsonArray("items")){if(n>=24)break;JsonObject row=e.getAsJsonObject();add(c,b,n++,Items.IRON_SWORD,row.get("name").getAsString()+" · "+row.get("source")+" #"+row.get("slot"),q->{JsonObject a=args("source",row.get("source").getAsString());a.add("slot",row.get("slot"));a.addProperty("count",1);JsonObject quote=RpgStorage.quote(q,a);confirmSale(q,quote);},"完整组件、耐久和槽位二次核对","单价 "+row.get("unitPrice")+" 灯币");}}
        default->throw new IllegalArgumentException("rpg_menu_not_found");}
        add(c,b,26,Items.COMPASS,"返回命格书",q->open(q,"guide",1));show(p,title,c,b);
    }
    static void skillDetail(ServerPlayer p,String id){JsonObject def=RpgSkills.definition(id);SimpleContainer c=new SimpleContainer(27);Map<Integer,Consumer<ServerPlayer>> b=new HashMap<>();add(c,b,4,Items.PAPER,def.get("title").getAsString(),q->{},def.get("description").getAsString(),"已学 Lv"+RpgSkills.level(p,id)+" · 熟练"+RpgSkills.uses(p,id),"冷却剩余 "+RpgSkills.remaining(p,id)+"ms");add(c,b,10,Items.EXPERIENCE_BOTTLE,"学习 / 升级",q->{RpgSkills.act(q,RpgSkills.level(q,id)==0?"skill_learn":"skill_upgrade",args("skillId",id));skillDetail(q,id);});add(c,b,12,Items.STICK,"绑定快捷施法",q->{RpgSkills.act(q,"skill_bind",args("skillId",id));giveBound(q,"focus");hint(q,"已绑定；手持灵纹法杖按交互瞬发。");});add(c,b,14,Items.BLAZE_POWDER,"立即施放",q->{q.closeContainer();RpgSkills.cast(q,id);});add(c,b,16,Items.ENCHANTING_TABLE,"刻印手持工具",q->{JsonObject a=args("skillId",id);a.addProperty("expectedSnbt",ModRequest.snbt(q,q.getMainHandItem()));RpgSkills.act(q,"skill_imprint",a);},"附近附魔台；消耗4级经验","潜行使用工具施放，须本人已学");add(c,b,26,Items.ARROW,"返回技能",q->open(q,"skills",1));show(p,def.get("title").getAsString(),c,b);}
    private static void confirmSale(ServerPlayer p,JsonObject quote){SimpleContainer c=new SimpleContainer(27);Map<Integer,Consumer<ServerPlayer>> b=new HashMap<>();add(c,b,4,Items.PAPER,quote.get("name").getAsString(),q->{},"耐久损耗 "+quote.get("damage")+" / "+quote.get("maxDamage"),"回收1件，收入 "+quote.get("price")+" 灯币","报价30秒有效，变化即拒绝");add(c,b,11,Items.EMERALD,"确认出售这1件",q->{RpgStorage.sell(q,quote.get("quoteId").getAsString());open(q,"recycle",1);});add(c,b,15,Items.BARRIER,"取消",q->open(q,"recycle",1));show(p,"确认装备回收",c,b);}
    private static void giveBound(ServerPlayer p,String type){for(ItemStack stack:p.getInventory().items){CompoundTag t=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(type.equals(t.getString("maw_bound_kind"))&&p.getUUID().toString().equals(t.getString("ownerUuid"))){hint(p,"这个绑定道具已在背包中。");return;}}if(p.getInventory().getFreeSlot()<0)throw new IllegalArgumentException("free_one_inventory_slot_first");ItemStack item=icon(type.equals("focus")?Items.STICK:Items.BOOK,type.equals("focus")?"灵纹法杖":"命格书",type.equals("focus")?"手持交互：本人绑定技能":"/mycli rpg 查看本人信息与玩法","绑定本人，不可丢弃");CompoundTag tag=new CompoundTag();tag.putBoolean("maw_bound",true);tag.putString("maw_bound_kind",type);tag.putString("ownerUuid",p.getUUID().toString());tag.putBoolean("maw_focus",type.equals("focus"));item.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));item.set(DataComponents.MAX_STACK_SIZE,1);p.getInventory().add(item);p.inventoryMenu.broadcastChanges();}
}
